//! evtx-tools — EVTX event parser and message formatter CLI.
//!
//! # Commands
//!
//! | Command | Platform | Description |
//! |---------|----------|-------------|
//! | parse   | All      | Parse .evtx → events.db / .csv |
//! | info    | All      | Query messages.db metadata |
//!
//! Single-file MessageDB (schema_version 7, ADR 0003) is the only accepted
//! messages input. There is no merge subcommand: re-run msgdb-dump.
//!
//! Message database (messages.db) is generated by the external
//! [msgdb-dump](https://github.com/kitsch-9527/msgdb-dump) tool.
//!
//! # Examples
//!
//! ```bash
//! # Parse with Chinese messages (default, falls back to English when unavailable)
//! evtx-tools parse security.evtx --msg-dir . -o events.db
//!
//! # Parse with English messages
//! evtx-tools parse security.evtx --msg-dir . --lang en-US -o events.db
//!
//! # Parse to CSV
//! evtx-tools parse security.evtx --msg-dir . -o events.csv --format csv
//! ```

use clap::{Parser, Subcommand};

mod cmd_info;

/// Built-in profile YAML definitions, embedded at compile time.
///
/// Each entry is `(profile_name, yaml_content)`. The path is relative to
/// this source file, resolving to `<workspace-root>/rules/<name>.yaml`.
const BUILTIN_PROFILES: &[(&str, &str)] = &[
    ("security", include_str!("../../rules/security.yaml")),
    ("persistence", include_str!("../../rules/persistence.yaml")),
    ("system", include_str!("../../rules/system.yaml")),
    ("remote", include_str!("../../rules/remote.yaml")),
    ("process", include_str!("../../rules/process.yaml")),
    ("powershell", include_str!("../../rules/powershell.yaml")),
    ("mssql", include_str!("../../rules/mssql.yaml")),
    ("web", include_str!("../../rules/web.yaml")),
];
mod cmd_parse;

#[derive(Parser)]
#[command(name = "evtx-tools", version, about = "EVTX event parser and analysis tool")]
struct Cli {
    #[command(subcommand)]
    command: Command,
}

#[derive(Subcommand)]
enum Command {
    /// Parse .evtx file(s) into events.db or events.csv
    Parse(ParseArgs),
    /// Show metadata about a messages.db file
    Info(InfoArgs),
}

#[derive(clap::Args)]
struct ParseArgs {
    /// Path to the .evtx file
    input: std::path::PathBuf,
    /// Output file path (.db or .csv)
    #[arg(short = 'o', long)]
    output: std::path::PathBuf,
    /// Output format: "db", "csv", or "both"
    #[arg(long, default_value = "db")]
    format: String,
    /// Directory containing hotech-msg-*.db files for auto-detection
    #[arg(long)]
    msg_dir: Option<std::path::PathBuf>,
    /// Explicit path to a messages.db file
    #[arg(long)]
    msg_db: Option<std::path::PathBuf>,
    /// Include raw XML output (default: false)
    #[arg(long)]
    with_xml: bool,
    /// Number of worker threads (0 = use all available cores)
    #[arg(long, default_value_t = 0)]
    threads: usize,
    /// Message language code (e.g. "zh-CN", "en-US"). Falls back to en-US
    /// when the requested language is not available for a given event.
    #[arg(long, default_value = "zh-CN")]
    lang: String,
    /// Built-in analysis profiles to apply (security, persistence, system, remote, process, powershell, mssql, web)
    #[arg(long)]
    profile: Vec<String>,
    /// Directory containing custom rule YAML files
    #[arg(long)]
    rules_dir: Option<std::path::PathBuf>,
    /// Skip statistics table generation
    #[arg(long)]
    no_stats: bool,
}

#[derive(clap::Args)]
struct InfoArgs {
    /// Path to a messages.db file
    db: std::path::PathBuf,
    /// Optional provider name filter
    #[arg(long)]
    provider: Option<String>,
}

fn main() {
    let cli = Cli::parse();

    let result = match &cli.command {
        Command::Parse(args) => cmd_parse::run_parse(args),
        Command::Info(args) => cmd_info::run_info(args),
    };

    if let Err(e) = result {
        eprintln!("Error: {e}");
        std::process::exit(1);
    }
}
